import fs from 'node:fs';
import fsPromises from 'node:fs/promises';
import path from 'node:path';
import type { DarwinRuntimeArch } from './bundledPaths';
import { machineProviderForArch, type BundledRuntimePaths } from './bundledPaths';

export type MachineProvider = 'libkrun' | 'applehv';

/**
 * Generate a private containers.conf for the bundled Podman helpers.
 */
export function buildContainersConf(options: {
  helperBinariesDir: string;
  provider: MachineProvider;
}): string {
  const helper = options.helperBinariesDir.replace(/\\/g, '/');
  return [
    '# Generated by Boundary Desktop — do not edit while the app manages Podman.',
    '[engine]',
    `helper_binaries_dir = ["${helper}"]`,
    '',
    '[machine]',
    `provider = "${options.provider}"`,
    '',
  ].join('\n');
}

export function readMachineProviderFromConf(content: string): MachineProvider | null {
  const match = content.match(/provider\s*=\s*"(libkrun|applehv)"/);
  return match ? (match[1] as MachineProvider) : null;
}

/**
 * Write containers.conf. Keeps a previously selected applehv/libkrun provider
 * so a libkrun→applehv fallback survives the next app launch.
 */
export async function ensureContainersConf(
  paths: BundledRuntimePaths,
  arch: DarwinRuntimeArch,
  providerOverride?: MachineProvider
): Promise<string> {
  await fsPromises.mkdir(paths.stateDir, { recursive: true });
  let existingProvider: MachineProvider | null = null;
  try {
    existingProvider = readMachineProviderFromConf(
      await fsPromises.readFile(paths.containersConfPath, 'utf8')
    );
  } catch {
    existingProvider = null;
  }
  const provider =
    providerOverride ?? existingProvider ?? machineProviderForArch(arch);
  const content = buildContainersConf({
    helperBinariesDir: paths.helperDir,
    provider,
  });
  await fsPromises.writeFile(paths.containersConfPath, content, 'utf8');
  return paths.containersConfPath;
}

export function writeMachineProviderConf(
  confPath: string,
  helperBinariesDir: string,
  provider: MachineProvider
): void {
  fs.writeFileSync(
    confPath,
    buildContainersConf({ helperBinariesDir, provider }),
    'utf8'
  );
}

/**
 * Env vars for invoking the bundled podman/compose binaries.
 */
export function buildBundledRuntimeEnv(
  paths: BundledRuntimePaths,
  baseEnv: NodeJS.ProcessEnv = process.env,
  dockerHost?: string
): NodeJS.ProcessEnv {
  const pathEnv = baseEnv.PATH ?? '';
  let provider: MachineProvider | null = null;
  try {
    provider = readMachineProviderFromConf(
      fs.readFileSync(paths.containersConfPath, 'utf8')
    );
  } catch {
    provider = null;
  }
  const env: NodeJS.ProcessEnv = {
    ...baseEnv,
    CONTAINERS_CONF: paths.containersConfPath,
    CONTAINERS_MACHINE_PROVIDER: provider ?? machineProviderForArch(),
    PATH: `${paths.binDir}${path.delimiter}${pathEnv}`,
  };
  if (dockerHost) {
    env.DOCKER_HOST = dockerHost;
  }
  return env;
}
